<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/bootstrap.php';
require_method('POST'); verify_csrf(); $farmer=require_role(['farmer']);
$providerId=filter_input(INPUT_POST,'provider_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$listingId=filter_input(INPUT_POST,'listing_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$pickup=filter_input(INPUT_POST,'pickup_location_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$delivery=filter_input(INPUT_POST,'delivery_location_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$description=normalize_text($_POST['produce_description']??'',160);$quantity=positive_decimal($_POST['quantity_kg']??null);$pickupDate=DateTimeImmutable::createFromFormat('!Y-m-d',$_POST['pickup_date']??'');$refrigeration=(int)($_POST['requires_refrigeration']??0)===1?1:0;
if(!$providerId||!$pickup||!$delivery||$description===''||$quantity===null||!$pickupDate||$pickup===$delivery)json_response(false,'Enter a valid provider, crop, quantity, distinct pickup and delivery locations, and pickup date.',[],422);
$pdo=db();$pdo->beginTransaction();try{$provider=fetch_one('SELECT tp.id,tp.user_id FROM transport_providers tp JOIN users u ON u.id=tp.user_id WHERE tp.id=:id AND u.status="active" FOR UPDATE',['id'=>$providerId]);if($provider===null)throw new RuntimeException('The selected transport provider is unavailable.');if($listingId!==null){$listing=fetch_one('SELECT id,quantity_available FROM produce_listings WHERE id=:id AND farmer_id=:farmer AND status="active" LIMIT 1',['id'=>$listingId,'farmer'=>$farmer['id']]);if($listing===null||$quantity>(float)$listing['quantity_available'])throw new RuntimeException('The selected listing cannot supply the requested quantity.');}$locationCount=fetch_one('SELECT COUNT(*) AS count FROM locations WHERE id IN (:pickup,:delivery)',['pickup'=>$pickup,'delivery'=>$delivery]);if((int)$locationCount['count']!==2)throw new RuntimeException('Choose valid pickup and delivery locations.');$reference=generate_reference('QAT');$pdo->prepare('INSERT INTO transport_requests (reference_code,farmer_id,provider_id,listing_id,pickup_location_id,delivery_location_id,produce_description,quantity_kg,requires_refrigeration,pickup_date) VALUES (:reference,:farmer,:provider,:listing,:pickup,:delivery,:description,:quantity,:refrigeration,:pickup_date)')->execute(['reference'=>$reference,'farmer'=>$farmer['id'],'provider'=>$providerId,'listing'=>$listingId,'pickup'=>$pickup,'delivery'=>$delivery,'description'=>$description,'quantity'=>$quantity,'refrigeration'=>$refrigeration,'pickup_date'=>$pickupDate->format('Y-m-d')]);$requestId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO transport_status_history (transport_request_id,status,changed_by_user_id,note) VALUES (:request,"requested",:actor,:note)')->execute(['request'=>$requestId,'actor'=>$farmer['id'],'note'=>'Farmer transport request submitted.']);create_notification((int)$provider['user_id'],'transport_request_created','New transport request',$farmer['full_name'].' requested pickup of '.number_format($quantity,0).' kg of '.$description.'.','transport/requests.php','transport_request',$requestId);$pdo->commit();audit_log((int)$farmer['id'],'transport_requested','transport_requests',$requestId,['reference'=>$reference]);json_response(true,'Transport request sent to the provider.',['request_id'=>$requestId,'reference'=>$reference]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,$e instanceof RuntimeException?$e->getMessage():'The transport request could not be saved.',[],422);}
